// the old items had sentenceA/sentenceB + imageA/imageB role-swapped pairs. Here each
// old item becomes ONE field-5.1 example: sentence = old sentenceA, audio = old <id>_a.mp3,
// target = old <id>_a.png, grammatical distractor = old <id>_b.png (the role-swapped scene).
